const shippingValid = s => s && ['name','address','city','postal','country'].every(k=>typeof s[k]==='string' && s[k].trim() && s[k].length<=200) && s.country==='US' && (s.state===undefined || typeof s.state==='string' && states.has(s.state.trim().toUpperCase()));
